#!/usr/bin/env python3
"""
Proof-of-Concept: Ambiguous Host Key Verification Policy (RFC 4251)

This script demonstrates how SSH clients that default to accepting unknown
host keys can be vulnerable to Man-in-the-Middle attacks. It simulates a
client connecting to a server without verifying the host key, showing how
an attacker could intercept the connection if the client's policy is too
permissive.

Note: This is a demonstration of the vulnerability concept. In a real attack,
the attacker would be on-path or performing DNS spoofing.
"""

import paramiko
import socket
import sys
import time

def create_mock_ssh_server(host_key_type='ssh-rsa'):
    """
    Create a simple mock SSH server for demonstration purposes.
    In a real scenario, this would be the attacker's server.
    """
    # Generate a new host key for the mock server
    if host_key_type == 'ssh-rsa':
        host_key = paramiko.RSAKey.generate(2048)
    else:
        host_key = paramiko.DSSKey.generate(1024)
    
    return host_key

def client_connection_attempt(target_host, target_port, policy='accept'):
    """
    Simulate an SSH client connection with different host key verification policies.
    
    Args:
        target_host: The target server hostname/IP
        target_port: The target server port
        policy: 'accept' (vulnerable), 'reject' (secure), or 'prompt' (interactive)
    """
    client = paramiko.SSHClient()
    
    # Configure host key policy based on the specified policy
    if policy == 'accept':
        # VULNERABLE: Automatically accept unknown host keys
        # This demonstrates the ambiguous default behavior mentioned in RFC 4251
        client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        print("[!] Client configured with AUTO-ACCEPT policy (VULNERABLE)")
        print("    This mimics clients that accept unknown host keys by default")
    elif policy == 'reject':
        # SECURE: Reject unknown host keys
        client.set_missing_host_key_policy(paramiko.RejectPolicy())
        print("[+] Client configured with REJECT policy (SECURE)")
        print("    This mimics clients that require explicit host key verification")
    else:
        # INTERACTIVE: Prompt user for unknown host keys
        client.set_missing_host_key_policy(paramiko.MissingHostKeyPolicy())
        print("[?] Client configured with PROMPT policy (INTERACTIVE)")
        print("    This mimics clients that ask the user to verify host keys")
    
    try:
        # Attempt connection
        print(f"\n[*] Attempting connection to {target_host}:{target_port}...")
        client.connect(
            hostname=target_host,
            port=target_port,
            username='testuser',
            password='testpass',
            timeout=5
        )
        
        if policy == 'accept':
            print("[!] SUCCESS: Connection established without host key verification!")
            print("    In a real attack, this would allow a MitM to intercept traffic.")
            return True
        else:
            print("[+] Connection established with proper verification.")
            return True
            
    except paramiko.SSHException as e:
        if "RejectPolicy" in str(e) or "BadHostKeyException" in str(e):
            print(f"[+] Connection rejected due to host key policy: {e}")
            return False
        else:
            print(f"[-] SSH Error: {e}")
            return False
    except socket.timeout:
        print("[-] Connection timed out")
        return False
    except Exception as e:
        print(f"[-] Connection failed: {e}")
        return False
    finally:
        client.close()

